#!/usr/bin/env Rscript
options(stringsAsFactors=FALSE,warn=1,width=180);a<-commandArgs(trailingOnly=TRUE);if(length(a)!=2L||a[[1]]!="--config")stop("usage")
suppressPackageStartupMessages({library(yaml);library(jsonlite);library(digest);library(scworkbench);library(slingshot);library(ggplot2);library(ggrepel)})
rcfg<-function(p){x<-yaml::read_yaml(p);b<-x$base_config;x$base_config<-NULL;if(is.null(b))return(x);utils::modifyList(rcfg(normalizePath(file.path(dirname(p),b))),x,keep.null=TRUE)};sha<-function(p)digest::digest(p,algo="sha256",file=TRUE);wtsv<-function(x,p,gz=FALSE){c<-if(gz)gzfile(p,"wt")else p;write.table(x,c,sep="\t",quote=TRUE,row.names=FALSE,na="NA");if(gz)close(c)};wjson<-function(x,p)jsonlite::write_json(x,p,pretty=TRUE,auto_unbox=TRUE,digits=NA,null="null",na="null");sp2<-function(x){if(is.data.frame(x)){data.frame(cell_id=x$cell_id,UMAP_1=x$x,UMAP_2=x$y)}else{x<-as.matrix(x);data.frame(cell_id=rownames(x),UMAP_1=x[,1],UMAP_2=x[,2])}}
cfgp<-normalizePath(a[[2]],mustWork=TRUE);cfg<-rcfg(cfgp);root<-cfg$storage$results_root;dirs<-setNames(file.path(root,c("01_tables","02_figures","03_reports","04_logs","05_objects","06_manifests")),c("tables","figures","reports","logs","objects","manifests"));sink(file.path(dirs[["logs"]],"03_plot_fixed_umap.log"),split=TRUE);on.exit(try(sink(),silent=TRUE),add=TRUE);mp<-file.path(dirs[["tables"]],"06_hvp_immgen_mappings.tsv");np<-file.path(dirs[["tables"]],"07_hvp_immgen_neighbors.tsv.gz");metp<-file.path(dirs[["tables"]],"08_hvp_external_metrics.tsv");maps<-read.delim(mp,check.names=FALSE,quote="\"");nei<-read.delim(gzfile(np),check.names=FALSE,quote="\"");mets<-read.delim(metp,check.names=FALSE,quote="\"");co<-unlist(cfg$visualization$candidate_order,use.names=FALSE);labs<-unlist(cfg$visualization$candidate_labels,use.names=TRUE)
b<-wb_open_bundle(cfg$inputs$source_bundle$path,validate=FALSE,read_only=TRUE);u<-sp2(wb_space(b,cfg$visualization$fixed_space));wb_close_bundle(b);rownames(u)<-u$cell_id;lf<-readRDS(cfg$inputs$authenticated_l4$pseudotime_path);z<-lf$key==cfg$inputs$authenticated_l4$key&is.finite(lf$value);lc<-merge(data.frame(cell_id=lf$cell_id[z],native_l4=lf$value[z]),u,by="cell_id");mod<-readRDS(cfg$inputs$authenticated_l4$model_path);cv<-slingCurves(mod)[[cfg$inputs$authenticated_l4$curve_name]];xy<-cv$s[cv$ord,,drop=FALSE];curve<-data.frame(UMAP_1=xy[,1],UMAP_2=xy[,2]);tail2<-tail(curve,2);arrowd<-data.frame(x=tail2$UMAP_1[1],y=tail2$UMAP_2[1],xend=tail2$UMAP_1[2],yend=tail2$UMAP_2[2]);ends<-rbind(transform(curve[1,],endpoint="native L4 start"),transform(curve[nrow(curve),],endpoint="native L4 end"))
nei$UMAP_1<-u[nei$reference_cell_id,"UMAP_1"];nei$UMAP_2<-u[nei$reference_cell_id,"UMAP_2"];groups<-split(nei,interaction(nei$candidate,nei$gsm,drop=TRUE));project<-function(r){r<-r[order(r$rank),];k<-max(r$distance);w<-if(k==0)as.numeric(r$distance==0)else exp(-(r$distance/k)^2);x<-as.matrix(r[,c("UMAP_1","UMAP_2")]);cen<-colSums(x*w)/sum(w);xc<-sweep(x,2,cen,"-");e<-eigen(crossprod(xc*sqrt(w/sum(w))),symmetric=TRUE);rad<-cfg$visualization$ellipse_scale*sqrt(pmax(e$values,0));th<-seq(0,2*pi,length.out=101);el<-sweep(cbind(cos(th),sin(th))%*%diag(rad,2)%*%t(e$vectors),2,cen,"+");list(p=data.frame(candidate=r$candidate[1],gsm=r$gsm[1],UMAP_1=cen[1],UMAP_2=cen[2]),e=data.frame(candidate=r$candidate[1],gsm=r$gsm[1],order=seq_along(th),UMAP_1=el[,1],UMAP_2=el[,2]))};pr<-lapply(groups,project);pl<-do.call(rbind,lapply(pr,`[[`,"p"));el<-do.call(rbind,lapply(pr,`[[`,"e"));pl<-merge(pl,maps[,c("candidate","gsm","population","lineage","predicted_bdev_cluster","provisional_native_l4")],by=c("candidate","gsm"));el<-merge(el,maps[,c("candidate","gsm","population","lineage")],by=c("candidate","gsm"));pl$candidate_label<-factor(labs[pl$candidate],levels=labs[co]);el$candidate_label<-factor(labs[el$candidate],levels=labs[co]);pl$detail<-paste0(pl$population," · ",pl$gsm)
pop<-c("LTHSC.34+.BM","LTHSC.34-.BM","STHSC.150-.BM","MPP3.48+.BM","MPP4.135+.BM","proB.CLP.BM","proB.FrA.BM","proB.FrBC.BM","B.FrE.BM","B.T1.Sp","B.T2.Sp","B.T3.Sp","B.Fo.Sp","B.MZ.Sp","B.Sp","B1b.PC");cols<-setNames(c("#3B4CC0","#5967B5","#748FFC","#3A86C8","#48BFE3","#168A83","#43AA8B","#79B473","#A7C957","#E9C46A","#F4A261","#E76F51","#D1495B","#9B5DE5","#7A5195","#5C4D7D"),pop);pl$population<-factor(pl$population,levels=pop);el$population<-factor(el$population,levels=pop);pad<-cfg$visualization$fixed_coordinate_padding_fraction;xr<-range(u$UMAP_1);yr<-range(u$UMAP_2);xl<-xr+c(-1,1)*diff(xr)*pad;yl<-yr+c(-1,1)*diff(yr)*pad
base<-function()ggplot()+geom_point(data=u,aes(UMAP_1,UMAP_2),color="#D5D5D5",size=.22,alpha=.35)+geom_point(data=lc,aes(UMAP_1,UMAP_2),color="#8E8E8E",size=.32,alpha=.42)+geom_path(data=curve,aes(UMAP_1,UMAP_2),color="white",linewidth=2.2)+geom_path(data=curve,aes(UMAP_1,UMAP_2),color="#151515",linewidth=.9)+geom_segment(data=arrowd,aes(x=x,y=y,xend=xend,yend=yend),arrow=grid::arrow(length=grid::unit(.13,"inches"),type="closed"),linewidth=.9)
p<-base()+geom_path(data=el,aes(UMAP_1,UMAP_2,group=interaction(candidate,gsm),color=population),linewidth=.42,alpha=.33)+geom_point(data=pl,aes(UMAP_1,UMAP_2,fill=population,shape=lineage),color="#111111",stroke=.45,size=2.8)+geom_label(data=ends,aes(UMAP_1,UMAP_2,label=endpoint),size=2.4,label.size=.15,fill=adjustcolor("white",.82))+scale_color_manual(values=cols,guide="none")+scale_fill_manual(values=cols,name="ImmGen population")+scale_shape_manual(values=c(B=21,"Stem&Prog"=24),name="Lineage")+facet_wrap(~candidate_label,ncol=2)+coord_equal(xlim=xl,ylim=yl,clip="off")+labs(title="Official scwbATAC HVP selection: depth-adjusted versus raw",subtitle="Same 28 frozen ImmGen libraries; points are 30-neighbor kernel barycenters",x="ATAC UMAP 1",y="ATAC UMAP 2",caption="Same 26,723-cell fixed Bdev ATAC UMAP and native L4. Both models were frozen before projection without refit.")+theme_classic(base_size=10.5)+theme(strip.text=element_text(face="bold"),plot.title=element_text(face="bold",size=15),legend.position="bottom",legend.box="vertical")+guides(fill=guide_legend(nrow=2,byrow=TRUE,override.aes=list(size=3,shape=21,color="#111111")))
ggsave(file.path(dirs[["figures"]],"01_hvp_depth_vs_raw_fixed_atac_umap.png"),p,width=15,height=8.5,dpi=240,bg="white");ggsave(file.path(dirs[["figures"]],"01_hvp_depth_vs_raw_fixed_atac_umap.pdf"),p,width=15,height=8.5,device=cairo_pdf,bg="white")
for(i in seq_along(co)){cc<-co[i];pp<-pl[pl$candidate==cc,];ee<-el[el$candidate==cc,];d<-base()+geom_path(data=ee,aes(UMAP_1,UMAP_2,group=gsm,color=population),linewidth=.6,alpha=.4)+geom_point(data=pp,aes(UMAP_1,UMAP_2,fill=population,shape=lineage),color="#111111",size=4,stroke=.65)+geom_label_repel(data=pp,aes(UMAP_1,UMAP_2,label=detail,color=population),seed=cfg$visualization$label_seed,max.overlaps=Inf,size=2.55,label.size=.15,fill=adjustcolor("white",.9),max.time=20)+geom_label(data=ends,aes(UMAP_1,UMAP_2,label=endpoint),size=2.4,label.size=.15,fill=adjustcolor("white",.82))+scale_color_manual(values=cols,guide="none")+scale_fill_manual(values=cols,guide="none")+scale_shape_manual(values=c(B=21,"Stem&Prog"=24),guide="none")+coord_equal(xlim=xl,ylim=yl,clip="off")+labs(title=paste(labs[[cc]],"on the fixed Bdev ATAC UMAP"),x="ATAC UMAP 1",y="ATAC UMAP 2",caption="Frozen 30-neighbor mapping; authenticated native L4 is diagnostic.")+theme_classic(base_size=11.5)+theme(plot.title=element_text(face="bold"),plot.margin=margin(10,45,10,10));stem=sprintf("%02d_%s_fixed_atac_umap_detail",i+1,cc);ggsave(file.path(dirs[["figures"]],paste0(stem,".png")),d,width=14,height=10.5,dpi=240,bg="white");ggsave(file.path(dirs[["figures"]],paste0(stem,".pdf")),d,width=14,height=10.5,device=cairo_pdf,bg="white")}
spec<-data.frame(field=c("within_population_to_between_population_latent_distance_ratio","replicate_predicted_cluster_agreement","unique_reference_neighbors","maximum_reference_hub_fraction","median_nearest_distance_over_reference_median","median_neighbor_sample_entropy","maximum_absolute_depth_latent_spearman","maximum_absolute_saturation_latent_spearman"),label=c("Within/between population distance (lower)","Replicate cluster agreement (higher)","Unique reference neighbors (higher)","Maximum reference hub fraction (lower)","Median support-distance ratio (lower)","Neighbor sample entropy (higher)","Maximum |depth–latent rho| (lower)","Maximum |saturation–latent rho| (lower)"));long<-do.call(rbind,lapply(seq_len(nrow(spec)),function(i)data.frame(candidate_label=labs[mets$candidate],metric=spec$label[i],value=mets[[spec$field[i]]])));long$candidate_label<-factor(long$candidate_label,levels=labs[co]);long$metric<-factor(long$metric,levels=rev(spec$label));pm<-ggplot(long,aes(value,candidate_label,color=candidate_label))+geom_line(aes(group=metric),color="#AAA")+geom_point(size=3)+geom_text(aes(label=formatC(value,digits=3,format="fg")),nudge_y=.16,size=2.7,show.legend=FALSE)+facet_wrap(~metric,scales="free_x",ncol=2)+scale_color_manual(values=c("#0072B2","#D55E00"),guide="none")+labs(title="Frozen HVP bulk-mapping diagnostics",subtitle="Official scwbATAC depth-adjusted and raw-binary 20k modes",x="Observed metric",y=NULL)+theme_classic(base_size=10.5)+theme(strip.text=element_text(face="bold",size=8.5),plot.title=element_text(face="bold",size=15));ggsave(file.path(dirs[["figures"]],"04_hvp_external_metric_comparison.png"),pm,width=13,height=10,dpi=240,bg="white");ggsave(file.path(dirs[["figures"]],"04_hvp_external_metric_comparison.pdf"),pm,width=13,height=10,device=cairo_pdf,bg="white")
wtsv(pl,file.path(dirs[["tables"]],"09_fixed_umap_placements.tsv"));wtsv(el,file.path(dirs[["tables"]],"10_fixed_umap_ellipses.tsv.gz"),TRUE);wjson(list(schema_version="bdev.hvp20k_fixed_umap.v1",status="complete",run_identity=cfg$run_identity,candidates=co,current_default_changed=FALSE),file.path(dirs[["reports"]],"02_hvp_fixed_umap_summary.json"));wjson(list(schema_version="bdev.hvp20k_figure_receipt.v1",status="complete",config_sha256=sha(cfgp),mappings_sha256=sha(mp),neighbors_sha256=sha(np),metrics_sha256=sha(metp)),file.path(dirs[["manifests"]],"04_figure_receipt.json"));cat("HVP fixed UMAP figures complete\n")
